using System;
using System.Drawing;
using System.Windows.Forms;
internal sealed class SessionPanel:UserControl {
 internal readonly RemoteSession Session;
 internal readonly TextBox command=new TextBox{Text="hostname & whoami"},output=new TextBox{Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,Font=new Font("Consolas",10),Dock=DockStyle.Fill};
 internal readonly NumericUpDown timeout=new NumericUpDown{Minimum=1,Maximum=300,Value=30},limit=new NumericUpDown{Minimum=1024,Maximum=1048576,Value=262144,Increment=1024};
 internal readonly Button run,cancel;internal readonly Label state=WorkspaceUi.Text(""),metadata=WorkspaceUi.Text("",true),viewing=WorkspaceUi.Text("",true);readonly Label target=WorkspaceUi.Text("",true);internal readonly ComboBox history=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Dock=DockStyle.Top};
 readonly SessionWorkspace workspace;readonly Button limits;readonly Control limitFields;int shown=-1;
 internal SessionPanel(RemoteSession session,SessionWorkspace owner,Action close,Action savedDevices){
  Session=session;workspace=owner;Dock=DockStyle.Fill;Padding=new Padding(16);Font=new Font("Segoe UI",10);
  var header=WorkspaceUi.Stack();WorkspaceUi.Add(header,WorkspaceUi.Pair(WorkspaceUi.Text(session.Target.DisplayName,false,14),WorkspaceUi.Button("Close tab",close),120));WorkspaceUi.Add(header,target);
  var numeric=WorkspaceUi.Pair(WorkspaceUi.Field("Timeout (seconds)",timeout),WorkspaceUi.Field("Maximum output (bytes)",limit),200);limitFields=numeric;numeric.Visible=false;
  limits=WorkspaceUi.Button("Limits: 30 seconds · 262144 bytes",()=>limitFields.Visible=!limitFields.Visible);limits.AccessibleName="Command limits disclosure";WorkspaceUi.Add(header,WorkspaceUi.Pair(WorkspaceUi.Field("Authorized command",command),limits,275));WorkspaceUi.Add(header,numeric);
  timeout.ValueChanged+=(s,e)=>limits.Text="Limits: "+timeout.Value+" seconds · "+limit.Value+" bytes";limit.ValueChanged+=(s,e)=>limits.Text="Limits: "+timeout.Value+" seconds · "+limit.Value+" bytes";
  Controls.Add(output);Controls.Add(header);header.Dock=DockStyle.Top;
  var bottom=WorkspaceUi.Stack();bottom.Dock=DockStyle.Bottom;var latest=WorkspaceUi.Button("Latest result",ViewLatest);latest.MinimumSize=Size.Empty;latest.Padding=new Padding(4);history.AccessibleName="Local session history (memory only)";WorkspaceUi.Add(bottom,WorkspaceUi.Pair(WorkspaceUi.Field("Session history",history),latest,130));WorkspaceUi.Add(bottom,viewing);metadata.Visible=false;WorkspaceUi.Add(bottom,state);
  var actions=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,WrapContents=true};run=WorkspaceUi.Button("Run command",async()=>await Run(),true);cancel=WorkspaceUi.Button("Cancel",()=>workspace.Cancel(Session));actions.Controls.Add(run);actions.Controls.Add(cancel);actions.Controls.Add(WorkspaceUi.Button("Saved devices",savedDevices));WorkspaceUi.Add(bottom,actions);Controls.Add(bottom);
  history.SelectedIndexChanged+=(s,e)=>{var entry=history.SelectedItem as SessionResult;if(entry!=null){if(entry.Result==null){output.Text=entry.Outcome;metadata.Text="No completed result · remote outcome unknown";}else RenderResult(entry.Result);viewing.Text="Viewing attempt "+entry.At.ToString("HH:mm:ss")+" · "+entry.Endpoint.Display+"\nCommand: "+(entry.Command.Length>120?entry.Command.Substring(0,120)+"…":entry.Command)+" · "+metadata.Text;viewing.AccessibleDescription="Viewing attempt "+entry.At.ToString("g")+" · "+entry.Endpoint.Display+" · Command: "+entry.Command+" · "+metadata.Text;}};WorkspaceUi.Help(this);GuiHelp.Set(command,"Run only owner-authorized commands on this tab's target. Confirmation shows exact endpoint.");GuiHelp.Set(output,"Output belongs to the labelled selected historical attempt, not necessarily the current operation/endpoint.");GuiHelp.Set(timeout,"1–300 seconds.");GuiHelp.Set(limit,"1024–1048576 bytes; extra output is truncated.");GuiHelp.Set(history,"Recent attempts for this tab only, never written to disk. Selecting history preserves the command draft and current operation.");GuiHelp.Set(latest,"View this tab's newest completed or unknown attempt; does not execute a command.");RefreshState();Appearance.Attach(this);
 }
 internal async System.Threading.Tasks.Task Run(){try{await workspace.RunAsync(Session,command.Text,(int)timeout.Value,(int)limit.Value);}catch(Exception ex){if(!IsDisposed){state.Text=ex.Message;state.AccessibleDescription=state.Text;}}}
 internal void ViewLatest(){if(history.Items.Count>0)history.SelectedIndex=history.Items.Count-1;}
 internal void RefreshState(){if(IsDisposed||Session.IsClosed)return;target.Text="Current target: "+Session.Target.DeviceId+" · "+Session.Target.Transport+" · "+Session.Endpoint.Display;state.Text="Current operation: "+Session.NavigationState+(Session.IsBusy?" · Cancel disconnects; remote result may be unknown.":" · "+(Session.State.Length>160?Session.State.Substring(0,160)+"…":Session.State))+(Session.HistoryEvicted?" · Older history removed at memory limit.":"");state.AccessibleDescription=Session.State;run.Enabled=!workspace.IsDeviceBusy(Session.Target.DeviceId)&&Session.HasCredential;cancel.Enabled=Session.IsBusy;command.Enabled=!Session.IsBusy;timeout.Enabled=limit.Enabled=!Session.IsBusy;
  GuiHelp.Set(run,run.Enabled?"Confirm and run a new bounded command for this target.":"A command/check already owns this Device ID; wait or cancel it.");GuiHelp.Set(cancel,cancel.Enabled?"Cancel/disconnect this request; remote process may still run.":"Unavailable while this tab is idle.");
  if(shown!=Session.HistoryRevision){bool first=shown<0;shown=Session.HistoryRevision;var selected=history.SelectedItem as SessionResult;bool followLatest=history.SelectedIndex==history.Items.Count-1;history.Items.Clear();foreach(var entry in Session.History)history.Items.Add(entry);if(history.Items.Count>0)history.SelectedIndex=first||followLatest||selected==null||!Session.History.Contains(selected)?history.Items.Count-1:Session.History.IndexOf(selected);}
 }
 void RenderResult(CommandResult result){output.Text=result.Stdout+Environment.NewLine+result.Stderr;metadata.Text="Exit: "+result.ExitCode+" · Duration: "+result.DurationMs+" ms"+(result.Truncated?" · Output was shortened at the configured limit":"");}
 protected override void Dispose(bool disposing){if(disposing&&!IsDisposed){command.Clear();output.Clear();history.Items.Clear();viewing.Text="";viewing.AccessibleDescription="";metadata.Text="";metadata.Dispose();}base.Dispose(disposing);}
}
